set local role authenticated;select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal1"}',true);
select is((public.complete_prep_task('e4500000-0000-4000-8000-000000000080','e4200000-0000-4000-8000-000000000080',2,1,false,'READINESS ONLY')).state,'completed','prep permission uses current restaurant date rather than session current_date');
select * from finish();rollback;
